import{_ as t,c as h,o as a,a2 as i}from"./chunks/framework.B7el9cAC.js";const m=JSON.parse('{"title":"Tài Nguyên Học Tập","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/resources.md","filePath":"appendix/resources.md","lastUpdated":1774640327000}'),o={name:"appendix/resources.md"};function e(c,n,l,r,u,g){return a(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="tai-nguyen-hoc-tap" tabindex="-1">Tài Nguyên Học Tập <a class="header-anchor" href="#tai-nguyen-hoc-tap" aria-label="Permalink to &quot;Tài Nguyên Học Tập&quot;">​</a></h1><blockquote><p>Tổng hợp tài nguyên hỗ trợ ôn thi Tin học THPT – tất cả đều <strong>miễn phí</strong></p></blockquote><hr><h2 id="🌐-chuong-2-–-mang-may-tinh" tabindex="-1">🌐 Chương 2 – Mạng Máy Tính <a class="header-anchor" href="#🌐-chuong-2-–-mang-may-tinh" aria-label="Permalink to &quot;🌐 Chương 2 – Mạng Máy Tính&quot;">​</a></h2><h3 id="cong-cu-truc-quan-hoa-mang" tabindex="-1">Công cụ trực quan hóa mạng <a class="header-anchor" href="#cong-cu-truc-quan-hoa-mang" aria-label="Permalink to &quot;Công cụ trực quan hóa mạng&quot;">​</a></h3><ul><li><strong>Cisco Packet Tracer</strong> (miễn phí cho sinh viên/học sinh) — phần mềm mô phỏng mạng, cho phép kéo thả router/switch/PC và thực hành cấu hình mạng.</li><li><strong>GNS3</strong> — phần mềm mô phỏng mạng nâng cao hơn (dùng khi đã hiểu cơ bản).</li></ul><h3 id="kiem-tra-đia-chi-ip-thuc-te" tabindex="-1">Kiểm tra địa chỉ IP thực tế <a class="header-anchor" href="#kiem-tra-đia-chi-ip-thuc-te" aria-label="Permalink to &quot;Kiểm tra địa chỉ IP thực tế&quot;">​</a></h3><ul><li>Gõ <code>ipconfig</code> (Windows) hoặc <code>ip addr</code> (Linux/Mac) trong terminal để xem địa chỉ IP máy tính của bạn.</li><li>Truy cập <a href="https://whatismyip.com" target="_blank" rel="noreferrer">whatismyip.com</a> để xem IP công cộng (IP mà Internet thấy).</li></ul><h3 id="video-hoc" tabindex="-1">Video học <a class="header-anchor" href="#video-hoc" aria-label="Permalink to &quot;Video học&quot;">​</a></h3><ul><li>YouTube: tìm &quot;Switch vs Router explained&quot; — có nhiều video hoạt hình dễ hiểu</li><li>YouTube: tìm &quot;TCP 3 way handshake animation&quot;</li></ul><hr><h2 id="🤖-chuong-3-–-tri-tue-nhan-tao" tabindex="-1">🤖 Chương 3 – Trí Tuệ Nhân Tạo <a class="header-anchor" href="#🤖-chuong-3-–-tri-tue-nhan-tao" aria-label="Permalink to &quot;🤖 Chương 3 – Trí Tuệ Nhân Tạo&quot;">​</a></h2><h3 id="trai-nghiem-ai-truc-tiep-mien-phi" tabindex="-1">Trải nghiệm AI trực tiếp (miễn phí) <a class="header-anchor" href="#trai-nghiem-ai-truc-tiep-mien-phi" aria-label="Permalink to &quot;Trải nghiệm AI trực tiếp (miễn phí)&quot;">​</a></h3><ul><li><strong>ChatGPT</strong> (chat.openai.com) — thử hỏi các câu hỏi khác nhau, nhận thấy khi nào AI &quot;tự tin sai&quot;</li><li><strong>Google Gemini</strong> (gemini.google.com) — so sánh câu trả lời với ChatGPT</li><li><strong>Google Translate</strong> — ví dụ NLP dịch máy</li><li><strong>QuillBot</strong> — ví dụ NLP paraphrase văn bản</li></ul><h3 id="tu-kiem-tra-hallucination" tabindex="-1">Tự kiểm tra hallucination <a class="header-anchor" href="#tu-kiem-tra-hallucination" aria-label="Permalink to &quot;Tự kiểm tra hallucination&quot;">​</a></h3><p>Thử hỏi AI: <em>&quot;Hãy liệt kê 5 cuốn sách về [chủ đề ít phổ biến] với tên tác giả và nhà xuất bản.&quot;</em> Sau đó Google kiểm tra từng cuốn. Bạn sẽ thấy rõ hallucination trong thực tế.</p><h3 id="he-goi-y-trong-thuc-te" tabindex="-1">Hệ gợi ý trong thực tế <a class="header-anchor" href="#he-goi-y-trong-thuc-te" aria-label="Permalink to &quot;Hệ gợi ý trong thực tế&quot;">​</a></h3><ul><li>Đăng nhập Netflix/YouTube/Spotify và để ý phần &quot;Được đề xuất cho bạn&quot; — đây là hệ gợi ý AI đang hoạt động ngay trước mắt bạn.</li></ul><hr><h2 id="🗄️-chuong-4-–-co-so-du-lieu-sql" tabindex="-1">🗄️ Chương 4 – Cơ Sở Dữ Liệu &amp; SQL <a class="header-anchor" href="#🗄️-chuong-4-–-co-so-du-lieu-sql" aria-label="Permalink to &quot;🗄️ Chương 4 – Cơ Sở Dữ Liệu &amp; SQL&quot;">​</a></h2><h3 id="luyen-tap-sql-online-mien-phi-khong-cai-đat" tabindex="-1">Luyện tập SQL online (miễn phí, không cài đặt) <a class="header-anchor" href="#luyen-tap-sql-online-mien-phi-khong-cai-đat" aria-label="Permalink to &quot;Luyện tập SQL online (miễn phí, không cài đặt)&quot;">​</a></h3><ul><li><strong>SQLiteOnline</strong> (sqliteonline.com) — gõ lệnh SQL ngay trong trình duyệt, thấy kết quả tức thì</li><li><strong>W3Schools SQL Tryit</strong> (w3schools.com/sql/tryme.asp) — có sẵn database mẫu để thực hành</li><li><strong>SQLZoo</strong> (sqlzoo.net) — bài tập SQL tương tác từ cơ bản đến nâng cao</li></ul><h3 id="cai-đat-co-so-du-lieu-thuc-neu-muon-thuc-hanh-sau-hon" tabindex="-1">Cài đặt cơ sở dữ liệu thực (nếu muốn thực hành sâu hơn) <a class="header-anchor" href="#cai-đat-co-so-du-lieu-thuc-neu-muon-thuc-hanh-sau-hon" aria-label="Permalink to &quot;Cài đặt cơ sở dữ liệu thực (nếu muốn thực hành sâu hơn)&quot;">​</a></h3><ul><li><strong>MySQL Community</strong> (miễn phí) + <strong>MySQL Workbench</strong> (giao diện đồ họa)</li><li><strong>DB Browser for SQLite</strong> — phần mềm nhẹ, dễ dùng, mở file <code>.db</code> SQLite</li></ul><h3 id="tai-lieu-tham-khao-sql" tabindex="-1">Tài liệu tham khảo SQL <a class="header-anchor" href="#tai-lieu-tham-khao-sql" aria-label="Permalink to &quot;Tài liệu tham khảo SQL&quot;">​</a></h3><ul><li><strong>W3Schools SQL</strong> (w3schools.com/sql) — tài liệu đầy đủ, có ví dụ chạy được ngay</li></ul><hr><h2 id="🌍-chuong-5-–-html-css" tabindex="-1">🌍 Chương 5 – HTML &amp; CSS <a class="header-anchor" href="#🌍-chuong-5-–-html-css" aria-label="Permalink to &quot;🌍 Chương 5 – HTML &amp; CSS&quot;">​</a></h2><h3 id="luyen-tap-html-css-online-mien-phi-khong-cai-đat" tabindex="-1">Luyện tập HTML/CSS online (miễn phí, không cài đặt) <a class="header-anchor" href="#luyen-tap-html-css-online-mien-phi-khong-cai-đat" aria-label="Permalink to &quot;Luyện tập HTML/CSS online (miễn phí, không cài đặt)&quot;">​</a></h3><ul><li><strong>CodePen</strong> (codepen.io) — viết HTML/CSS/JS và xem kết quả ngay, không cần đăng ký</li><li><strong>JSFiddle</strong> (jsfiddle.net) — tương tự CodePen</li><li><strong>W3Schools Tryit</strong> (w3schools.com/html/tryit.asp) — thực hành với ví dụ trong tài liệu</li></ul><h3 id="trinh-soan-thao-code-mien-phi" tabindex="-1">Trình soạn thảo code miễn phí <a class="header-anchor" href="#trinh-soan-thao-code-mien-phi" aria-label="Permalink to &quot;Trình soạn thảo code miễn phí&quot;">​</a></h3><ul><li><strong>Visual Studio Code</strong> (code.visualstudio.com) — miễn phí, nhẹ, cài extension LiveServer để xem HTML thay đổi realtime</li><li><strong>Notepad++</strong> (Windows) — đơn giản hơn, phù hợp người mới bắt đầu</li></ul><h3 id="cach-xem-html-cua-bat-ky-trang-web-nao" tabindex="-1">Cách xem HTML của bất kỳ trang web nào <a class="header-anchor" href="#cach-xem-html-cua-bat-ky-trang-web-nao" aria-label="Permalink to &quot;Cách xem HTML của bất kỳ trang web nào&quot;">​</a></h3><ol><li>Mở trang web bất kỳ trong Chrome/Firefox</li><li>Nhấn chuột phải → &quot;Kiểm tra&quot; (hoặc F12)</li><li>Tab <strong>Elements</strong> — xem cấu trúc HTML thực tế</li><li>Tab <strong>Styles</strong> — xem CSS đang được áp dụng</li></ol><h3 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to &quot;Tài liệu tham khảo&quot;">​</a></h3><ul><li><strong>MDN Web Docs</strong> (developer.mozilla.org) — tài liệu HTML/CSS/JS chuẩn và đầy đủ nhất</li><li><strong>W3Schools HTML</strong> (w3schools.com/html) — dễ đọc hơn, phù hợp người mới</li></ul><hr><h2 id="⚖️-chuong-6-–-đao-đuc-nghe-it" tabindex="-1">⚖️ Chương 6 – Đạo Đức &amp; Nghề IT <a class="header-anchor" href="#⚖️-chuong-6-–-đao-đuc-nghe-it" aria-label="Permalink to &quot;⚖️ Chương 6 – Đạo Đức &amp; Nghề IT&quot;">​</a></h2><h3 id="tu-kiem-tra-mat-khau-co-bi-lo-chua" tabindex="-1">Tự kiểm tra mật khẩu có bị lộ chưa <a class="header-anchor" href="#tu-kiem-tra-mat-khau-co-bi-lo-chua" aria-label="Permalink to &quot;Tự kiểm tra mật khẩu có bị lộ chưa&quot;">​</a></h3><ul><li><strong>Have I Been Pwned</strong> (haveibeenpwned.com) — nhập email để kiểm tra có trong vụ rò rỉ dữ liệu nào không (an toàn, chỉ kiểm tra hash)</li></ul><h3 id="hieu-ve-an-toan-thong-tin" tabindex="-1">Hiểu về an toàn thông tin <a class="header-anchor" href="#hieu-ve-an-toan-thong-tin" aria-label="Permalink to &quot;Hiểu về an toàn thông tin&quot;">​</a></h3><ul><li><strong>Cybrary</strong> (cybrary.it) — khóa học bảo mật mạng miễn phí</li><li><strong>Google Digital Garage</strong> — khóa học an toàn số cơ bản miễn phí</li></ul><h3 id="kham-pha-nghe-it" tabindex="-1">Khám phá nghề IT <a class="header-anchor" href="#kham-pha-nghe-it" aria-label="Permalink to &quot;Khám phá nghề IT&quot;">​</a></h3><ul><li><strong>Topcv.vn</strong> và <strong>ITviec.com</strong> — xem các vị trí công việc IT thực tế, mức lương, yêu cầu kỹ năng</li><li><strong>Stackoverflow Developer Survey</strong> — khảo sát hàng năm về nghề lập trình viên toàn cầu</li></ul><hr><h2 id="📚-tai-nguyen-on-thi-tong-hop" tabindex="-1">📚 Tài Nguyên Ôn Thi Tổng Hợp <a class="header-anchor" href="#📚-tai-nguyen-on-thi-tong-hop" aria-label="Permalink to &quot;📚 Tài Nguyên Ôn Thi Tổng Hợp&quot;">​</a></h2><h3 id="trang-web-on-thi" tabindex="-1">Trang web ôn thi <a class="header-anchor" href="#trang-web-on-thi" aria-label="Permalink to &quot;Trang web ôn thi&quot;">​</a></h3><ul><li><strong>Hocmai.vn</strong> — bài giảng video môn Tin học THPT</li><li><strong>VnDoc.com</strong> — đề thi thử Tin học THPT các năm</li></ul><h3 id="ung-dung-hoc-flashcard" tabindex="-1">Ứng dụng học flashcard <a class="header-anchor" href="#ung-dung-hoc-flashcard" aria-label="Permalink to &quot;Ứng dụng học flashcard&quot;">​</a></h3><ul><li><strong>Anki</strong> (apps.ankiweb.net) — tạo thẻ ghi nhớ, dùng thuật toán lặp lại theo khoảng cách (spaced repetition) — hiệu quả nhất để nhớ lâu</li><li><strong>Quizlet</strong> (quizlet.com) — tạo và học flashcard, có thể tìm bộ thẻ Tin học THPT của người khác đã làm sẵn</li></ul><h3 id="youtube-kenh-hoc-tin-hoc-tieng-viet" tabindex="-1">YouTube kênh học Tin học tiếng Việt <a class="header-anchor" href="#youtube-kenh-hoc-tin-hoc-tieng-viet" aria-label="Permalink to &quot;YouTube kênh học Tin học tiếng Việt&quot;">​</a></h3><ul><li>Tìm kiếm &quot;Tin học THPT lớp 12&quot; trên YouTube — nhiều thầy cô chia sẻ bài giảng miễn phí</li></ul><hr><h2 id="🛠️-cong-cu-ho-tro-hoc" tabindex="-1">🛠️ Công Cụ Hỗ Trợ Học <a class="header-anchor" href="#🛠️-cong-cu-ho-tro-hoc" aria-label="Permalink to &quot;🛠️ Công Cụ Hỗ Trợ Học&quot;">​</a></h2><h3 id="ghi-chu-va-to-chuc-kien-thuc" tabindex="-1">Ghi chú và tổ chức kiến thức <a class="header-anchor" href="#ghi-chu-va-to-chuc-kien-thuc" aria-label="Permalink to &quot;Ghi chú và tổ chức kiến thức&quot;">​</a></h3><ul><li><strong>Notion</strong> (notion.so) — miễn phí cho cá nhân, ghi chú có cấu trúc tốt</li><li><strong>Obsidian</strong> (obsidian.md) — ghi chú dạng liên kết, tốt cho học kiến thức có liên quan</li></ul><h3 id="kiem-tra-ban-than" tabindex="-1">Kiểm tra bản thân <a class="header-anchor" href="#kiem-tra-ban-than" aria-label="Permalink to &quot;Kiểm tra bản thân&quot;">​</a></h3><ul><li>Sau khi đọc xong một mục, <strong>tắt tài liệu</strong> và thử giải thích lại khái niệm bằng lời của mình (phương pháp Feynman).</li><li>Dùng <strong>ChatGPT</strong> hỏi: <em>&quot;Em vừa học về [chủ đề]. Hãy hỏi em 5 câu hỏi trắc nghiệm về chủ đề này.&quot;</em></li></ul><h3 id="nhom-hoc-tap" tabindex="-1">Nhóm học tập <a class="header-anchor" href="#nhom-hoc-tap" aria-label="Permalink to &quot;Nhóm học tập&quot;">​</a></h3><ul><li>Lập nhóm học 3–5 người, mỗi người &quot;dạy&quot; lại một mục cho cả nhóm — dạy người khác là cách hiểu sâu nhất.</li></ul><hr><p><em>💡 Lưu ý: Tất cả tài nguyên đề xuất ở trên đều miễn phí hoặc có bản miễn phí đầy đủ tính năng. Không cần mua bất kỳ khóa học trả phí nào để ôn thi tốt nghiệp THPT.</em></p>',62)])])}const d=t(o,[["render",e]]);export{m as __pageData,d as default};
